import React from "react";
import { ShortcutsHelp } from "./utils/keyboardShortcuts";
import "./utils/keyboardShortcuts.css";
import Tutorial from "./components/Tutorial";

function Home({ authToken, userEmail, onNavigate, onLogout, darkMode, toggleDarkMode }) {
  const [showNavDropdown, setShowNavDropdown] = React.useState(false);
  const [showUserDropdown, setShowUserDropdown] = React.useState(false);
  const [userDropdownTimeout, setUserDropdownTimeout] = React.useState(null);
  const [showFabMenu, setShowFabMenu] = React.useState(false);
  const [showShortcuts, setShowShortcuts] = React.useState(false);
  const [showHelpModal, setShowHelpModal] = React.useState(false);
  const [showTutorial, setShowTutorial] = React.useState(false);
  const [unreadCount, setUnreadCount] = React.useState(0);

  // Check if user has seen tutorial on first visit
  React.useEffect(() => {
    const tutorialCompleted = localStorage.getItem('tutorial_completed');
    if (!tutorialCompleted && authToken) {
      // Show tutorial for first-time users
      setShowTutorial(true);
    }
    
    // Fetch unread notifications
    const fetchUnreadNotifications = async () => {
      try {
        const res = await fetch(`http://localhost:8000/notifications/${userEmail}`);
        const data = await res.json();
        if (data.status === "success") {
          setUnreadCount(data.unread_count);
        }
      } catch (err) {
        console.error("Error fetching notifications:", err);
      }
    };

    if (userEmail) {
      fetchUnreadNotifications();
    }
  }, [authToken, userEmail]);

  const handleUserMouseEnter = () => {
    if (userDropdownTimeout) clearTimeout(userDropdownTimeout);
    setShowUserDropdown(true);
  };

  const handleUserMouseLeave = () => {
    const timeout = setTimeout(() => setShowUserDropdown(false), 200);
    setUserDropdownTimeout(timeout);
  };

  const handleSettings = () => {
    onNavigate("app-settings");
  };

  const handleHelp = () => {
    setShowHelpModal(true);
  };

  return (
    <div className="animated-bg" style={{ minHeight: "100vh" }}>
      {/* Header */}
      <header className="header">
        <div className="header-content">
          <div className="logo" onClick={() => onNavigate("main")} style={{ cursor: "pointer" }}>
            🍳 SmartChef
          </div>
          <div className="nav-buttons">
            {authToken ? (
              <>
                {/* Right side - Menu & User */}
                <div style={{ display: "flex", gap: "0.8rem", alignItems: "center", marginLeft: "auto", marginRight: "-0.5rem" }}>
                  {/* Navigation Dropdown */}
                  <div 
                    style={{ position: "relative" }}
                    onMouseEnter={() => setShowNavDropdown(true)}
                    onMouseLeave={() => setShowNavDropdown(false)}
                  >
                    <button
                      className="btn btn-outline"
                      style={{ padding: "0.7rem 1.2rem", fontSize: "1.5rem" }}
                    >
                      ☰
                    </button>
                    {showNavDropdown && (
                      <div className="nav-dropdown">
                        <button
                          className="nav-dropdown-item"
                          onClick={() => {
                            onNavigate("dashboard");
                            setShowNavDropdown(false);
                          }}
                        >
                          📈 Dashboard
                        </button>
                        <button
                          className="nav-dropdown-item"
                          onClick={() => {
                            onNavigate("history");
                            setShowNavDropdown(false);
                          }}
                        >
                          📊 History
                        </button>
                        <button
                          className="nav-dropdown-item"
                          onClick={() => {
                            onNavigate("goals");
                            setShowNavDropdown(false);
                          }}
                        >
                          🎯 Goals
                        </button>
                      </div>
                    )}
                  </div>
                  
                  <div style={{
                    width: "1px",
                    height: "30px",
                    background: "rgba(255,255,255,0.3)",
                    margin: "0 0.5rem"
                  }}></div>

                  {/* Notifications Bell */}
                  <button
                    className="btn btn-outline"
                    onClick={() => onNavigate('notifications')}
                    style={{ 
                      padding: "0.7rem 1.2rem", 
                      fontSize: "1.5rem", 
                      background: "rgba(255,255,255,0.2)",
                      position: "relative"
                    }}
                    title="Notifications"
                  >
                    🔔
                    {unreadCount > 0 && (
                      <span style={{
                        position: "absolute",
                        top: "-5px",
                        right: "-5px",
                        background: "#ff6b35",
                        color: "white",
                        borderRadius: "50%",
                        width: "24px",
                        height: "24px",
                        display: "flex",
                        alignItems: "center",
                        justifyContent: "center",
                        fontSize: "0.75rem",
                        fontWeight: "700",
                        border: "2px solid white"
                      }}>
                        {unreadCount}
                      </span>
                    )}
                  </button>
                  
                  {/* User Dropdown */}
                  <div 
                    style={{ position: "relative" }}
                    onMouseEnter={handleUserMouseEnter}
                    onMouseLeave={handleUserMouseLeave}
                  >
                    <button
                      className="btn btn-outline"
                      style={{ 
                        display: "flex",
                        alignItems: "center",
                        gap: "0.5rem"
                      }}
                    >
                      👤 {userEmail}
                      <span style={{ 
                        fontSize: "0.7rem",
                        transition: "transform 0.3s",
                        display: "inline-block",
                        transform: showUserDropdown ? "rotate(90deg)" : "rotate(0deg)"
                      }}>►</span>
                    </button>
                    {showUserDropdown && (
                      <div className="user-dropdown">
                        <button className="user-dropdown-item" onClick={() => alert('🚧 Profile - Coming soon!')}>
                          <span className="dropdown-icon">👤</span>
                          Profile
                        </button>
                        
                        <button className="user-dropdown-item" onClick={() => {
                          onNavigate("personal-data");
                          setShowUserDropdown(false);
                        }}>
                          <span className="dropdown-icon">📊</span>
                          Personal Data
                        </button>
                        
                        <button className="user-dropdown-item" onClick={() => {
                          onNavigate("account-settings");
                          setShowUserDropdown(false);
                        }}>
                          <span className="dropdown-icon">🔑</span>
                          Account Settings
                        </button>

                        <button className="user-dropdown-item" onClick={() => {
                          onNavigate("app-settings");
                          setShowUserDropdown(false);
                        }}>
                          <span className="dropdown-icon">⚙️</span>
                          App Settings
                        </button>
                        
                        <button className="user-dropdown-item" onClick={() => {
                          setShowTutorial(true);
                          setShowUserDropdown(false);
                        }}>
                          <span className="dropdown-icon">🎓</span>
                          Replay Tutorial
                        </button>
                        
                        <div className="user-dropdown-divider"></div>
                        <button className="user-dropdown-item logout-item" onClick={onLogout}>
                          <span className="dropdown-icon">🚪</span>
                          Logout
                        </button>
                      </div>
                    )}
                  </div>
                </div>
              </>
            ) : (
              <div style={{ display: "flex", gap: "0.5rem", marginLeft: "auto" }}>
                <button
                  className="btn btn-outline"
                  onClick={() => onNavigate("login")}
                >
                  Login
                </button>
                <button
                  className="btn btn-secondary"
                  onClick={() => onNavigate("register")}
                >
                  Register
                </button>
              </div>
            )}
          </div>
        </div>
      </header>

      {/* Main Content Container */}
      <div style={{ maxWidth: "1200px", margin: "0 auto", padding: "3rem 2rem" }}>
        {/* Hero Section */}
        <div style={{ marginBottom: "6rem" }}>
          <h1 style={{ 
            fontSize: "2.8rem", 
            fontWeight: "700", 
            color: "#1a1a1a",
            marginBottom: "1.5rem",
            lineHeight: "1.3"
          }}>
            Know exactly what you're eating
          </h1>
          <p style={{ 
            fontSize: "1.1rem", 
            color: "#555",
            fontWeight: "400",
            maxWidth: "600px",
            lineHeight: "1.7"
          }}>
            Photograph your meal. Get nutritional facts in seconds. Make informed choices about your diet with confidence.
          </p>
        </div>

        {/* Features Grid */}
        <div style={{ 
          display: "grid", 
          gridTemplateColumns: "repeat(auto-fit, minmax(320px, 1fr))", 
          gap: "2rem", 
          marginBottom: "6rem"
        }}>
          {/* Feature 1 */}
          <div style={{ 
            padding: "2.5rem",
            background: "#f9f9f9",
            borderRadius: "12px",
            borderLeft: "4px solid #ff6b35"
          }}>
            <h3 style={{ 
              fontSize: "1.4rem", 
              fontWeight: "600", 
              color: "#1a1a1a",
              marginBottom: "0.75rem"
            }}>
              Accurate Recognition
            </h3>
            <p style={{ 
              fontSize: "0.95rem", 
              color: "#666", 
              lineHeight: "1.6"
            }}>
              Point your camera at any meal and get an instant breakdown of ingredients and portions. Works with hundreds of dishes and cuisines.
            </p>
          </div>

          {/* Feature 2 */}
          <div style={{ 
            padding: "2.5rem",
            background: "#f9f9f9",
            borderRadius: "12px",
            borderLeft: "4px solid #ff6b35"
          }}>
            <h3 style={{ 
              fontSize: "1.4rem", 
              fontWeight: "600", 
              color: "#1a1a1a",
              marginBottom: "0.75rem"
            }}>
              Complete Nutrition Data
            </h3>
            <p style={{ 
              fontSize: "0.95rem", 
              color: "#666", 
              lineHeight: "1.6"
            }}>
              Get calories, macros, vitamins, minerals, and more for each ingredient. Export detailed reports as PDF anytime you need them.
            </p>
          </div>

          {/* Feature 3 */}
          <div style={{ 
            padding: "2.5rem",
            background: "#f9f9f9",
            borderRadius: "12px",
            borderLeft: "4px solid #ff6b35"
          }}>
            <h3 style={{ 
              fontSize: "1.4rem", 
              fontWeight: "600", 
              color: "#1a1a1a",
              marginBottom: "0.75rem"
            }}>
              Track & Improve
            </h3>
            <p style={{ 
              fontSize: "0.95rem", 
              color: "#666", 
              lineHeight: "1.6"
            }}>
              Monitor your goals, weight, and habits over time. View trends with clear charts and build sustainable routines.
            </p>
          </div>
        </div>

        {/* Additional Features Section */}
        <div style={{ marginBottom: "6rem" }}>
          <h2 style={{ 
            fontSize: "1.8rem", 
            fontWeight: "600", 
            color: "#1a1a1a",
            marginBottom: "2.5rem"
          }}>
            Everything you need, nothing you don't
          </h2>
          
          <div style={{ 
            display: "grid", 
            gridTemplateColumns: "repeat(auto-fit, minmax(250px, 1fr))", 
            gap: "1.5rem"
          }}>
            {[
              { title: "Security First", desc: "Two-factor authentication keeps your data safe" },
              { title: "Multiple Themes", desc: "Light, dark, and custom color schemes" },
              { title: "Advanced Filters", desc: "Search and browse all your past analyses" },
              { title: "Weight Tracking", desc: "Monitor progress with visual timeline" },
              { title: "Goal Setting", desc: "Set targets and track your journey" },
              { title: "PDF Reports", desc: "Export meals for records or professionals" }
            ].map((item, idx) => (
              <div key={idx} style={{ 
                padding: "1.5rem",
                background: "white",
                border: "1px solid #e5e5e5",
                borderRadius: "8px"
              }}>
                <h4 style={{ 
                  fontSize: "1rem", 
                  fontWeight: "600", 
                  color: "#1a1a1a",
                  marginBottom: "0.5rem"
                }}>
                  {item.title}
                </h4>
                <p style={{ 
                  fontSize: "0.9rem", 
                  color: "#777"
                }}>
                  {item.desc}
                </p>
              </div>
            ))}
          </div>
        </div>

        {/* Final CTA */}
        {!authToken ? (
          <div style={{ 
            textAlign: "center",
            padding: "3rem",
            background: "#fff3ef",
            borderRadius: "12px"
          }}>
            <h2 style={{ 
              fontSize: "1.8rem", 
              fontWeight: "600", 
              color: "#1a1a1a",
              marginBottom: "1rem"
            }}>
              Start tracking today
            </h2>
            <p style={{ 
              fontSize: "1rem", 
              color: "#666",
              marginBottom: "2rem"
            }}>
              Free account. No credit card required.
            </p>
            <div style={{ display: "flex", gap: "1rem", justifyContent: "center", flexWrap: "wrap" }}>
              <button
                className="btn btn-primary"
                onClick={() => onNavigate("register")}
                style={{ 
                  padding: "0.9rem 2rem", 
                  fontSize: "1rem",
                  background: "#ff6b35",
                  color: "white",
                  border: "none",
                  borderRadius: "8px",
                  fontWeight: "600",
                  cursor: "pointer"
                }}
              >
                Sign Up
              </button>
              <button
                className="btn btn-outline"
                onClick={() => onNavigate("login")}
                style={{ 
                  padding: "0.9rem 2rem", 
                  fontSize: "1rem",
                  background: "white",
                  color: "#ff6b35",
                  border: "2px solid #ff6b35",
                  borderRadius: "8px",
                  fontWeight: "600",
                  cursor: "pointer"
                }}
              >
                Login
              </button>
            </div>
          </div>
        ) : (
          <div style={{ 
            textAlign: "center",
            padding: "3rem",
            background: "#ff6b35",
            borderRadius: "12px",
            color: "white"
          }}>
            <h2 style={{ 
              fontSize: "1.8rem", 
              fontWeight: "600",
              marginBottom: "1rem"
            }}>
              Ready to get started?
            </h2>
            <p style={{ 
              fontSize: "1rem", 
              marginBottom: "2rem",
              opacity: 0.95
            }}>
              Take a photo of your next meal to see how easy nutrition tracking can be.
            </p>
            <button
              className="btn"
              onClick={() => onNavigate("analyze-food")}
              style={{ 
                background: "white",
                color: "#ff6b35",
                padding: "0.9rem 2rem",
                fontSize: "1rem",
                fontWeight: "600",
                border: "none",
                borderRadius: "8px",
                cursor: "pointer"
              }}
            >
              Analyze a Meal
            </button>
          </div>
        )}
      </div>

      {/* Floating Action Button with Expandable Menu */}
      <div className="fab-container">
        {/* Menu Items (appear when expanded) */}
        <button
          className={`fab-menu-item fab-menu-item-1 ${showFabMenu ? 'show' : ''}`}
          onClick={toggleDarkMode}
          title={darkMode ? "Switch to Light Mode" : "Switch to Dark Mode"}
        >
          {darkMode ? "☀️" : "🌙"}
        </button>
        <button
          className={`fab-menu-item fab-menu-item-2 ${showFabMenu ? 'show' : ''}`}
          onClick={handleSettings}
          title="Settings"
        >
          ⚙️
        </button>
        <button
          className={`fab-menu-item fab-menu-item-3 ${showFabMenu ? 'show' : ''}`}
          onClick={handleHelp}
          title="Help & Support"
        >
          ❓
        </button>
        <button
          className={`fab-menu-item fab-menu-item-4 ${showFabMenu ? 'show' : ''}`}
          onClick={() => setShowShortcuts(true)}
          title="Keyboard Shortcuts (press ?)"
        >
          ⌨️
        </button>
        
        {/* Main FAB Button */}
        <button
          className={`fab-main ${showFabMenu ? 'active' : ''}`}
          onClick={() => setShowFabMenu(!showFabMenu)}
          title="Menu"
        >
          <span className="fab-icon">{showFabMenu ? '×' : '+'}</span>
        </button>
      </div>

      {/* Keyboard Shortcuts Help Modal */}
      {showShortcuts && (
        <ShortcutsHelp 
          onClose={() => setShowShortcuts(false)}
          customShortcuts={{
            'h': { description: 'Mergi la Home (acum)', action: 'navigate-home' }
          }}
        />
      )}

      {/* Help & Support Modal */}
      {showHelpModal && (
        <div style={{
          position: "fixed",
          top: 0,
          left: 0,
          right: 0,
          bottom: 0,
          background: "rgba(0, 0, 0, 0.6)",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          zIndex: 10000
        }}>
          <div style={{
            background: "white",
            borderRadius: "20px",
            padding: "2rem",
            maxWidth: "500px",
            width: "90%",
            boxShadow: "0 10px 40px rgba(0, 0, 0, 0.3)",
            position: "relative"
          }}>
            {/* Close Button (X) */}
            <button
              onClick={() => setShowHelpModal(false)}
              style={{
                position: "absolute",
                top: "1rem",
                right: "1rem",
                background: "none",
                border: "none",
                fontSize: "2rem",
                cursor: "pointer",
                color: "#666",
                width: "40px",
                height: "40px",
                display: "flex",
                alignItems: "center",
                justifyContent: "center",
                transition: "all 0.2s ease"
              }}
              onMouseEnter={(e) => {
                e.target.style.color = "#ff6b35";
                e.target.style.transform = "scale(1.2)";
              }}
              onMouseLeave={(e) => {
                e.target.style.color = "#666";
                e.target.style.transform = "scale(1)";
              }}
            >
              ×
            </button>

            {/* Modal Content */}
            <h2 style={{ 
              fontSize: "1.8rem", 
              color: "#ff6b35", 
              marginBottom: "1.5rem",
              paddingRight: "2rem"
            }}>
              ❓ Help & Support
            </h2>

            <div style={{ color: "#333", lineHeight: "1.8" }}>
              <p style={{ marginBottom: "1rem", fontWeight: "600", color: "#666" }}>
                For assistance:
              </p>
              <ul style={{ marginBottom: "1.5rem", paddingLeft: "1.5rem" }}>
                <li style={{ marginBottom: "0.5rem" }}>📧 <strong>Email:</strong> support@smartchef.ro</li>
                <li style={{ marginBottom: "0.5rem" }}>🐛 <strong>Report bugs</strong> on GitHub</li>
              </ul>

              <p style={{ marginBottom: "1rem", fontWeight: "600", color: "#666" }}>
                Quick Tips:
              </p>
              <ul style={{ paddingLeft: "1.5rem" }}>
                <li style={{ marginBottom: "0.5rem" }}>📸 Upload clear food images</li>
                <li style={{ marginBottom: "0.5rem" }}>🌙 Use dark mode for better viewing</li>
                <li style={{ marginBottom: "0.5rem" }}>📄 Export analyses as PDF</li>
                <li>⭐ Mark favorites with stars</li>
              </ul>
            </div>

            {/* OK Button */}
            <button
              onClick={() => setShowHelpModal(false)}
              style={{
                marginTop: "2rem",
                width: "100%",
                padding: "1rem",
                background: "linear-gradient(135deg, #ff8c42 0%, #ff6b35 100%)",
                color: "white",
                border: "none",
                borderRadius: "12px",
                fontSize: "1rem",
                fontWeight: "600",
                cursor: "pointer",
                transition: "all 0.3s ease"
              }}
              onMouseEnter={(e) => {
                e.target.style.transform = "translateY(-2px)";
                e.target.style.boxShadow = "0 6px 20px rgba(255, 107, 53, 0.3)";
              }}
              onMouseLeave={(e) => {
                e.target.style.transform = "translateY(0)";
                e.target.style.boxShadow = "none";
              }}
            >
              OK
            </button>
          </div>
        </div>
      )}

      {/* Onboarding Tutorial */}
      {showTutorial && (
        <Tutorial onComplete={() => setShowTutorial(false)} />
      )}
    </div>
  );
}

export default Home;
